solution.javascript:
function isPalindrome(head) {
  let slow = head
  let fast = head
  while (fast && fast.next) {
    slow = slow.next
    fast = fast.next.next
  }
  let prev = null
  let curr = slow
  while (curr) {
    const nxt = curr.next
    curr.next = prev
    prev = curr
    curr = nxt
  }
  let left = head
  let right = prev
  while (right) {
    if (left.val !== right.val) return false
    left = left.next
    right = right.next
  }
  return true
}
